const webhook = $('Lead Intake Webhook').first().json;
const body = webhook.body ?? webhook;

// Explicitly read tenant configuration from Get Business Config.
// The read is unfiltered, so it emits one item per tenant. Resolve the row
// matching THIS business_id rather than taking .first(), which could only ever
// match row 1 and rejected every other tenant with 403.
const configs = $('Get Business Config').all();

const businessId = body.business_id
  ? String(body.business_id).trim()
  : '';

const config =
  configs.find((c) => String(c.json.business_id || '').trim() === businessId)
    ?.json ?? null;

const _configFound = !!config;

const _active =
  _configFound &&
  String(config.active || '').trim().toLowerCase() === 'true';

const now = new Date();

function rid(prefix) {
  return prefix + '_' + now.getTime() + '_' +
    Math.random().toString(36).slice(2, 10);
}

function esc(v) {
  return String(v == null ? '' : v)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function fnv1a(str) {
  let h = 0x811c9dc5;

  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }

  return ('00000000' + h.toString(16)).slice(-8);
}

function classifyUrgency(declared, msg) {
  if (
    declared &&
    ['emergency', 'high', 'normal', 'low']
      .includes(String(declared).toLowerCase())
  ) {
    return String(declared).toLowerCase();
  }

  const m = String(msg || '').toLowerCase();

  if (/emergency|urgent|asap|immediately|right now|burst|leak|flood|no water|no hot water|lockout|fire|frozen pipe|smoke/i.test(m)) {
    return 'emergency';
  }

  if (/soon|today|this week|quickly|as fast|tomorrow/i.test(m)) {
    return 'high';
  }

  if (/just browsing|researching|not sure|eventually|curious|compare/i.test(m)) {
    return 'low';
  }

  return 'normal';
}

function score(f) {
  let s = 0;
  const m = String(f.message || '').toLowerCase();

  if (f.email) s += 15;
  if (f.phone) s += 15;
  if (f.service) s += 15;
  if (f.city) s += 10;
  if (f.state) s += 5;
  if (f.name) s += 10;
  if (f.urgency === 'high') s += 10;
  if (f.urgency === 'emergency') s += 20;
  if (m.length > 40) s += 5;
  if (/quote|estimate|price|cost|book|schedule|install|repair|fix|replace|need|leak/i.test(m)) s += 10;
  if (/emergency|urgent|asap|burst|leak|flood|no water|lockout/i.test(m)) s += 5;
  if (/am |ready|this week|today|specific|available/i.test(m)) s += 5;

  return Math.min(100, s);
}

// Runtime-compatible booking-link validation.
// Do NOT use the URL constructor because it is unavailable
// in the n8n Code node sandbox.
function safeBookingLink(value, leadId) {
  let raw = String(value || '').trim();

  if (!raw) return '';

  // Preserve {{lead_id}} substitution behavior.
  raw = raw.replace(
    /\{\{\s*lead_id\s*\}\}/g,
    encodeURIComponent(leadId)
  );

  // HTTPS only.
  if (!/^https:\/\/[^\s"'<>]+$/i.test(raw)) {
    return '';
  }

  // Reject control/dangerous characters.
  if (/[\r\n<>"'`]/.test(raw)) {
    return '';
  }

  // Preserve existing lead_id attribution.
  if (/[?&]lead_id=/.test(raw)) {
    return raw;
  }

  return raw +
    (raw.includes('?') ? '&' : '?') +
    'lead_id=' +
    encodeURIComponent(leadId);
}

const name = body.name || '';
const email = String(body.email || '').trim().toLowerCase();
const phone = String(body.phone || '').trim();
const normPhone = phone.replace(/\D/g, '');
const message = body.message || '';

const normMessage = String(message || '')
  .trim()
  .toLowerCase()
  .replace(/\s+/g, ' ');

const service = body.service || '';

const srcType = String(
  body.source_type || 'web_form'
);

const srcId = body.source_id
  ? String(body.source_id).trim()
  : '';

const urgency = classifyUrgency(
  body.urgency,
  message
);

// Deterministic idempotency:
// explicit key > upstream event ID > derived hash.
let idempotencyKey;

if (body.idempotency_key) {
  idempotencyKey = String(body.idempotency_key);
} else if (srcId) {
  idempotencyKey =
    businessId + '|' + srcType + '|' + srcId;
} else {
  idempotencyKey =
    'auto_' +
    fnv1a([
      businessId,
      srcType,
      normPhone,
      email,
      normMessage
    ].join('|'));
}

const leadId = body.lead_id || rid('lead');

// Booking-link precedence:
// 1. trusted request-supplied HTTPS link
// 2. trusted business_config HTTPS link
// 3. empty
const bodyLink = String(
  body.booking_link || ''
).trim();

const configLink = config
  ? String(config.booking_link || '').trim()
  : '';

let bookingLink = bodyLink
  ? safeBookingLink(bodyLink, leadId)
  : '';

if (!bookingLink && configLink) {
  bookingLink = safeBookingLink(
    configLink,
    leadId
  );
}

const lead = {
  lead_id: leadId,
  business_id: businessId,
  created_at: now.toISOString(),
  updated_at: now.toISOString(),
  source_type: srcType,
  source_id: srcId,
  name: name,
  phone: phone,
  email: email,
  message: message,
  service: service,
  niche: body.niche ||
    (config ? (config.niche || '') : '') ||
    '',
  city: body.city || '',
  state: body.state || '',
  zip: body.zip || '',
  urgency: urgency,
  score: score({
    name: name,
    phone: phone,
    email: email,
    service: service,
    city: body.city,
    state: body.state,
    message: message,
    urgency: urgency
  }),
  status: 'new',
  booking_link: bookingLink,
  booking_link_sent: false,
  booked: false,
  followup_count: 0,
  next_followup_at: '',
  last_contact_at: '',
  last_customer_response_at: '',
  idempotency_key: idempotencyKey,
  notes: body.notes || ''
};

const merged = Object.assign({}, lead, {
  _configFound: _configFound,
  _active: _active,

  _fromEmailPresent: !!(
    config &&
    config.from_email
  ),

  _replyToPresent: !!(
    config &&
    config.reply_to_email
  ),

  _bookingLinkPresent: !!bookingLink,

  business_name: config
    ? config.business_name
    : '',

  owner_name: config
    ? config.owner_name
    : '',

  owner_email: config
    ? config.owner_email
    : '',

  reply_to_email: config
    ? config.reply_to_email
    : '',

  from_email: config
    ? config.from_email
    : '',

  followup_delay_hours: config
    ? Number(config.followup_delay_hours || 24)
    : 24,

  max_followups: config
    ? Number(config.max_followups || 3)
    : 3,

  timezone: config
    ? config.timezone
    : 'America/Chicago'
});

// HTML-safe copies for email templates.
// Underscore fields are not persisted by autoMapInputData.
merged._esc_lead_id = esc(lead.lead_id);
merged._esc_business_name = esc(merged.business_name);
merged._esc_name = esc(name);
merged._esc_phone = esc(phone);
merged._esc_email = esc(email);
merged._esc_service = esc(service);
merged._esc_city = esc(body.city || '');
merged._esc_state = esc(body.state || '');
merged._esc_zip = esc(body.zip || '');
merged._esc_message = esc(message);
merged._esc_booking_link = esc(bookingLink);
merged._esc_urgency = esc(urgency);
merged._esc_source_type = esc(srcType);
merged._esc_source_id = esc(srcId);
merged._esc_created_at = esc(lead.created_at);

return [{ json: merged }];

const rows = $input.all();
const lead = $('Resolve Config & Normalize Lead').first().json;
const key = String(lead.idempotency_key || '');
const srcId = String(lead.source_id || '');
const srcType = String(lead.source_type || '');
const bid = String(lead.business_id || '');
const normPhone = String(lead.phone || '').replace(/\D/g, '');
const normEmail = String(lead.email || '').trim().toLowerCase();
let reason = '';
const dup = rows.some(r => {
  const j = r.json;
  const rowBid = String(j.business_id || '');
  if (key && j.idempotency_key && String(j.idempotency_key) === key && rowBid === bid) { reason = 'idempotency_key'; return true; }
  // Tenant-scoped: source identifiers only match within the same business_id (V4 fix).
  if (srcId && j.source_id && String(j.source_id) === srcId && String(j.source_type || '') === srcType && rowBid === bid) { reason = 'source_id'; return true; }
  // Digits-only phone normalization for comparison; stored phone value is untouched.
  if (normPhone && j.phone && rowBid === bid && String(j.phone).replace(/\D/g, '') === normPhone) { reason = 'phone'; return true; }
  if (normEmail && j.email && rowBid === bid && String(j.email).trim().toLowerCase() === normEmail) { reason = 'email'; return true; }
  return false;
});
return [{ json: Object.assign({}, lead, { _isDuplicate: dup, _duplicateReason: reason }) }];

const lead = $('Check Duplicate').first().json;
const delay = Number(lead.followup_delay_hours || 24);
const next = new Date(Date.now() + delay * 3600 * 1000).toISOString();
return [{ json: Object.assign({}, lead, {
  next_followup_at: next,
  updated_at: new Date().toISOString(),
  booking_link_sent: lead.booking_link ? true : Boolean(lead.booking_link_sent)
}) }];

// $input here is the output of the Google Sheets 'Update Lead Next Follow-up' node,
// which replaces $json with the sheet row. The tenant config and escaped HTML
// fields the email templates depend on only exist on 'Compute Next Follow-up',
// so read from that node explicitly.
const lead = $('Compute Next Follow-up').first().json;
return [{ json: lead }];

const errWrap = $input.first().json;
const lead = $('Check Duplicate').first().json;
const SECRET_RE = /(bearer)(\s+)([^,}"'`\s]+)|(secret|token|password|api[_ -]?key|authorization|bearer)((?:\\?["'])?\s*[:=]\s*)("(?:[^"\\]|\\.)*"|\\"(?:[^"\\]|\\.)*?\\"|'(?:[^'\\]|\\.)*'|`(?:[^`\\]|\\.)*`|bearer\s+[^,}"'`\s]+|[^,}"'`\s]+)/gi;
// Redacts a secret whatever delimiter or quoting surrounds it, so the shape a
// provider happens to emit cannot decide whether the value is reached. The value
// may be a double-quoted, single-quoted or backtick literal, a JSON-escaped
// double-quoted literal (which is what JSON.stringify hands the object branch),
// a `Bearer <credential>` pair, or a bare token. `redactSecret` re-emits the
// leading delimiter it found, quote and backslash included, so a redacted JSON
// payload stays well-formed and parseable instead of being cut in half. The
// leading branch still catches a bare "Bearer <credential>" with no keyword
// separator, and the value group may itself be "Bearer <credential>", so a
// header-style "Authorization: Bearer <jwt>" is consumed whole rather than
// leaving the JWT behind.
const redactSecret = (m, bearer, ws, token, keyword, sep, value) => {
  if (bearer) return bearer + ws + '[REDACTED]';
  const open = /^(\\?["'`])/.exec(value);
  const q = open ? open[1] : '';
  return keyword + sep + q + '[REDACTED]' + q;
};
function sanitize(v){
  if (v === null || v === undefined) return '';
  if (typeof v === 'object') return JSON.stringify(v).replace(SECRET_RE, redactSecret);
  return String(v).replace(SECRET_RE, redactSecret);
}
const rawErr = errWrap.error !== undefined ? errWrap.error : (errWrap.json && errWrap.json.error);
const msg = (typeof rawErr === 'object' && rawErr !== null) ? String(rawErr.message || JSON.stringify(rawErr)) : String(rawErr || 'unknown email error');
return [{ json: {
  error_id: 'err_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8),
  created_at: new Date().toISOString(),
  workflow: '01 - Lead Intake',
  node: 'Customer Acknowledgment',
  business_id: sanitize(lead.business_id),
  lead_id: sanitize(lead.lead_id),
  error_message: sanitize('customer_email_failed: ' + msg).slice(0, 2000),
  execution_id: $execution.id,
  payload: sanitize({ lead_id: lead.lead_id, business_id: lead.business_id }).slice(0, 4000),
  resolved: false
} }];

